#!/usr/bin/env bash
set -euo pipefail

# Production hotfix — 2026-09-23
#
# Fixes: Quality Analytics' incident-rate-by-month joint counts stopped
# updating after the 2026-09-16 changeover. QualityAnalyticsController::
# buildIncidentRateData() treated the seeded September quality_joint_history
# override (629, documented as a *partial* 9/1-9/16 baseline) as an absolute
# replacement instead of a floor to build on — so every elevation completed
# after 9/16 was silently excluded from that chart/PDF. The standalone
# Joints Completed report was NOT affected (it has no override logic and
# always computed live).
#
# This is a STOPGAP patched into the running container's writable layer —
# per docker-compose.prod.yml (pre-built GHCR image, no source bind-mount),
# it will be wiped on the next image pull/redeploy. The real fix is
# committed in the dev repo (ForgeDesk3-dev) for the next real release.
#
# Run this ON THE REAL PROD BOX, from the directory where
# docker-compose.prod.yml is the default compose file. Requires no
# arguments; safe to re-run (migration is idempotent, file writes are
# full-file replacements).
#
# What it does:
#   1. Adds a new migration: quality_joint_history.as_of_date (nullable
#      date), and sets it to 2026-09-16 on the '2026-09' row.
#   2. Replaces app/Models/QualityJointHistory.php (adds as_of_date to
#      $fillable + a date cast).
#   3. Replaces app/Http/Controllers/Api/QualityAnalyticsController.php
#      (buildIncidentRateData() now adds live joint_qty completed on/after
#      as_of_date on top of the override, instead of replacing it).
#   4. Fixes file ownership back to www-data (root wrote them).
#   5. Runs the migration for real (--force, non-interactive).
#   6. Clears config/view cache.
#
# Verified locally against a copy of production-shaped data before this was
# handed over: September now returns 629 (baseline) + 313 (live joints
# completed since 9/16) = 942, matching a raw FdWoElevation sum.

echo "==> Writing migration: 2026_09_23_000001_add_as_of_date_to_quality_joint_history.php"
docker compose exec -T -u root app sh -c 'base64 -d > database/migrations/2026_09_23_000001_add_as_of_date_to_quality_joint_history.php' <<'B64_MIGRATION'

B64_MIGRATION

echo "==> Writing app/Models/QualityJointHistory.php"
docker compose exec -T -u root app sh -c 'base64 -d > app/Models/QualityJointHistory.php' <<'B64_MODEL'

B64_MODEL

echo "==> Writing app/Http/Controllers/Api/QualityAnalyticsController.php"
docker compose exec -T -u root app sh -c 'base64 -d > app/Http/Controllers/Api/QualityAnalyticsController.php' <<'B64_CONTROLLER'

B64_CONTROLLER

echo "==> Fixing ownership"
docker compose exec -u root app chown www-data:www-data \
  database/migrations/2026_09_23_000001_add_as_of_date_to_quality_joint_history.php \
  app/Models/QualityJointHistory.php \
  app/Http/Controllers/Api/QualityAnalyticsController.php

echo "==> Running migration"
docker compose exec app php artisan migrate --force

echo "==> Clearing caches"
docker compose exec app php artisan config:clear
docker compose exec app php artisan view:clear

echo "==> Done."
